    private static Button Button(Node parent,string text,string name=""){var button=new Button{Text=text};if(name.Length>0)button.Name=name;parent.AddChild(button);return button;}
    private GArray Types=>GD.Load<GDScript>("res://scripts/actors/physics/destruction/destruction_geometry.gd").GetScriptConstantMap()["TYPES"].AsGodotArray();
    public void build(VBoxContainer owner)
    {
        owner.Set("queued",false);var host=Host(owner);var actor=Actor(owner);var updaters=host.Get("_updaters").AsGodotArray();var callbacks=owner.Get("callbacks").AsGodotArray();foreach(var callback in callbacks)updaters.Remove(callback);callbacks.Clear();int start=updaters.Count;foreach(var child in owner.GetChildren()){owner.RemoveChild(child);child.QueueFree();}var row=new HBoxContainer();owner.AddChild(row);var kinds=new OptionButton{Name="DamageType",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,FitToLongestItem=false};foreach(var title in Types)kinds.AddItem(title.AsString());row.AddChild(kinds);var preview=new CheckButton{Text="Preview cuts",Name="PreviewFracturePattern",ButtonPressed=actor.GetMeta("damage_pattern_preview",false).AsBool()};owner.AddChild(preview);preview.Toggled+=value=>{actor.SetMeta("damage_pattern_preview",value);actor.SetMeta("damage_viewport_tool",value);};var add=Button(row,"＋","AddDamageOperation");add.TooltipText="Add a non-destructive operation at the current timeline time";add.Pressed+=()=>{var updated=Operations(owner).Duplicate(true);string id=_data.new_id();owner.Set("selected",id);updated[id]=_definition.operation(kinds.Selected,Math.Max(0,Time(actor)));_definition.edit(Model(owner),actor,updated,"Add damage operation");actor.SetMeta("damage_selected_operation",id);build(owner);};var operations=Operations(owner);owner.Set("layout",GD.Hash(Keys(operations)));string selected=owner.Get("selected").AsString();if(selected.Length==0)selected=actor.GetMeta("damage_selected_operation","").AsString();if(!operations.ContainsKey(selected))selected=operations.Count>0?operations.Keys.First().AsString():"";owner.Set("selected",selected);var keys=Keys(operations);
        for(int i=0;i<keys.Count;i++){string id=keys[i].AsString();var op=operations[id].AsGodotDictionary();var line=new HBoxContainer();owner.AddChild(line);var enabled=new CheckBox{ButtonPressed=op.GetValueOrDefault("enabled",true).AsBool()};line.AddChild(enabled);enabled.Toggled+=value=>change(owner,id,"enabled",value,false);var select=Button(line,Types[op["type"].AsInt32()].AsString());select.ToggleMode=true;select.ButtonPressed=id==selected;select.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;select.ClipText=true;select.Pressed+=()=>{owner.Set("selected",id);actor.SetMeta("damage_selected_operation",id);build(owner);};foreach(int direction in new[]{-1,1}){var move=Button(line,direction<0?"↑":"↓");move.Disabled=i+direction<0||i+direction>=keys.Count;move.Pressed+=()=>{string error=_authoring.operation_action(Model(owner),actor,id,direction<0?"Up":"Down");if(error.Length>0){var message=new AcceptDialog{Title="Operation order",DialogText=error};owner.AddChild(message);message.PopupCentered();message.Confirmed+=message.QueueFree;}build(owner);};}var remove=Button(line,"×");remove.TooltipText="Remove operation and restore its source geometry";remove.Pressed+=()=>{var updated=Operations(owner).Duplicate(true);updated.Remove(id);_definition.edit(Model(owner),actor,updated,"Remove damage operation");build(owner);};}
        if(operations.ContainsKey(selected))BuildSelected(owner,selected,operations[selected].AsGodotDictionary());var status=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart};status.AddThemeFontSizeOverride("font_size",12);owner.AddChild(status);var snapshot=Button(owner,"Save evaluated mesh…");snapshot.TooltipText="Save the actual deformed/fractured geometry at this playhead as an ordinary mesh resource. The source and editable operations are preserved.";snapshot.Pressed+=()=>GD.Load<GDScript>("res://scripts/actors/physics/physics_mesh_snapshot.gd").Call("prompt",owner,Model(owner),actor);void Update(){if(!GodotObject.IsInstanceValid(status))return;foreach(var editor in owner.GetTree().GetNodesInGroup("actor_timeline_editors"))if(editor.Get("model").AsGodotObject()==Model(owner)){var states=editor.Get("physics").AsGodotObject().Get("display_states").AsGodotDictionary();status.Text=states.GetValueOrDefault(actor.Get("id"),new Settings()).AsGodotDictionary().GetValueOrDefault("destruction_error","Closed convex solids: cuts/carving/fracture. Open sheets: tears. Original geometry is preserved.").AsString();}}updaters.Add(Callable.From(Update));Update();host.Call("_prepare_buttons");for(int i=start;i<updaters.Count;i++)callbacks.Add(updaters[i]);
    }
    private void BuildSelected(VBoxContainer owner,string id,Settings op)
    {
        var actor=Actor(owner);var host=Host(owner);var actions=new HBoxContainer();owner.AddChild(actions);foreach(string action in new[]{"Duplicate","Reset"}){var button=Button(actions,action,"Damage"+action);button.Pressed+=()=>{_authoring.operation_action(Model(owner),actor,id,action);build(owner);};}var pathButton=new CheckButton{Text="Draw fracture path",ButtonPressed=actor.GetMeta("damage_path_tool",false).AsBool()};owner.AddChild(pathButton);pathButton.Toggled+=value=>{actor.SetMeta("damage_path_tool",value);actor.SetMeta("damage_fragment_tool",false);actor.SetMeta("damage_viewport_tool",true);};var resistance=new CheckBox{Text="Physical resistance",TooltipText="On: cutting energy is resisted by the local physical material. Off: direct geometry editing.",ButtonPressed=op.GetValueOrDefault("physical",false).AsBool()};owner.AddChild(resistance);resistance.Toggled+=value=>change(owner,owner.Get("selected").AsString(),"physical",value,false);var handle=Button(owner,"◎  Position in viewport","DamageViewportHandle");handle.ToggleMode=true;handle.ButtonPressed=actor.GetMeta("damage_viewport_tool",false).AsBool();handle.Toggled+=value=>{actor.SetMeta("damage_viewport_tool",value);actor.SetMeta("damage_fragment_tool",false);actor.SetMeta("damage_selected_operation",owner.Get("selected"));};int kind=op["type"].AsInt32();var parameters=new List<string>{"time"};if(kind is 3 or 4 or 6 or 7 or 8 or 9 or 10 or 11 or 12 or 13)parameters.Add("radius");if(kind is 3 or 4 or 5 or 7 or 8 or 9 or 10 or 11 or 12)parameters.Add("amount");if(kind==9)parameters.Add("falloff");if(kind is 1 or 2)parameters.AddRange(new[]{"pieces","seed","irregularity"});if(kind is 0 or 1 or 2 or 5 or 14)parameters.AddRange(new[]{"impulse","direction_bias"});if(kind==14)parameters.Add("energy");if(op.GetValueOrDefault("physical",false).AsBool())parameters.Add("energy");
        foreach(string key in parameters){var line=new HBoxContainer();owner.AddChild(line);string title=key switch{"time"=>"Start (s)","amount"=>"Depth / angle (rad)","pieces"=>"Fracture pieces","impulse"=>"Separation speed",_=>key.Capitalize()};var label=new Label{Text=title,TooltipText=title,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis};line.AddChild(label);var property=_properties.create(new StringName(key),title,op.GetValueOrDefault(key,1.0),true);if(key is not ("pieces" or "seed"))host.Call("_add_keyframe_button",line,actor,property,new[]{"destruction_operations",id,key},op.GetValueOrDefault(key,1.0));var number=Number("Damage_"+key,key=="amount",key is "pieces" or "seed"?1:.01,op.GetValueOrDefault(key,1).AsDouble());owner.AddChild(number);host.Get("_updaters").AsGodotArray().Add(Callable.From(()=>UpdateNumber(owner,number,key)));Bind(owner,number,id,key,v=>v);}
        foreach(string key in new[]{"position","direction"}){var heading=new HBoxContainer();owner.AddChild(heading);heading.AddChild(new Label{Text=key.Capitalize(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});host.Call("_add_keyframe_button",heading,actor,_properties.create(new StringName(key),key.Capitalize(),op.GetValueOrDefault(key,Vector3.Zero),true),new[]{"destruction_operations",id,key},op.GetValueOrDefault(key,Vector3.Zero));for(int axis=0;axis<3;axis++){int component=axis;var line=new HBoxContainer();owner.AddChild(line);line.AddChild(new Label{Text=new[]{"X","Y","Z"}[axis]});var number=Number("Damage_"+key+"_"+axis,true,.01,op.GetValueOrDefault(key,Vector3.Zero).AsVector3()[axis]);number.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;line.AddChild(number);Variant Value(double v){var path=new[]{"destruction_operations",id,key};var vector=_animation.sampled_value(actor,path,Time(actor),_animation.value_at_path(actor,path)).AsVector3();vector[component]=(float)v;return vector;}Bind(owner,number,id,key,Value);host.Get("_updaters").AsGodotArray().Add(Callable.From(()=>UpdateNumber(owner,number,key,component)));}}
    }
